CREATE TABLE b64_param (ss_item_sk INT, n BIGINT);
INSERT OVERWRITE INTO b64_param SELECT ss_item_sk, count(*) FROM store_sales ss JOIN date_dim d ON d.d_date_sk = ss.ss_sold_date_sk WHERE d.d_year = 2001 AND ss_item_sk <= 30 GROUP BY ss_item_sk;
SELECT * FROM b64_param ORDER BY ss_item_sk

